function panel(t,b){return `<div class="panel"><h2>${esc(t)}</h2><p>${esc(b)}</p></div>`}function filterRows(i){const q=i.value.toLowerCase();i.closest('.panel').querySelectorAll('tbody tr,.case-row').forEach(r=>r.style.display=r.innerText.toLowerCase().includes(q)?'':'none')}
function openCommandPalette(){const old=document.getElementById('command-palette');if(old){old.remove();return}document.body.insertAdjacentHTML('beforeend',`<div id="command-palette" class="modal-backdrop"><div class="command-palette"><div class="command-head"><strong>Navigation rapide</strong><button class="modal-close" onclick="openCommandPalette()">×</button></div><input id="command-input" placeholder="Rechercher une section…" autocomplete="off"><div class="command-list">${visibleNavItems().map(([id,label])=>`<button onclick="navigateTo('${id}');document.getElementById('command-palette')?.remove()"><span>${label}</span><small>/${id}</small></button>`).join('')}</div></div></div>`);const input=document.getElementById('command-input');input?.focus();input?.addEventListener('input',()=>{const q=input.value.toLowerCase();document.querySelectorAll('.command-list button').forEach(b=>b.hidden=!b.innerText.toLowerCase().includes(q))})}
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openCommandPalette()}if(e.key==='Escape')document.getElementById('command-palette')?.remove()});document.addEventListener('click',e=>{const b=e.target.closest('.billing-offer-btn');if(!b)return;selectClientBillingOffer(b.dataset.billingOffer||'',b.dataset.billingName||'',b.dataset.billingPrice||'',b.dataset.billingId||'')});

