async function approveCase(id){if(!confirm(rdT('Confirmer l’approbation humaine de ce dossier ?')))return;try{await api(`/v1/cases/${encodeURIComponent(id)}/approve`,{method:'POST',body:'{}'});toast(rdT('Décision approuvée'),'success');openCase(id)}catch(e){toast(e.message,'error')}}
async function prepareSubmission(id){if(!confirm(rdT('Préparer une soumission ? Aucune action externe ne sera exécutée.')))return;try{await api(`/v1/cases/${encodeURIComponent(id)}/submit`,{method:'POST',headers:{'Idempotency-Key':crypto.randomUUID()},body:'{}'});toast(rdT('Soumission préparée, aucune action externe exécutée'),'success');openCase(id)}catch(e){toast(e.message,'error')}}
async function downloadPrivacyExport(){
 try{
  const response=await fetch('/v1/privacy/export',{headers:{Authorization:'Bearer '+state.token}});
  if(!response.ok)throw new Error('Export impossible');
  const blob=await response.blob();
  const url=URL.createObjectURL(blob);
  const a=document.createElement('a');a.href=url;a.download='review-defense-rgpd-export.json';document.body.appendChild(a);a.click();a.remove();URL.revokeObjectURL(url);
  toast('Export RGPD généré','success');
 }catch(e){toast(e.message||'Export impossible','error')}
}
